// MT2009_PLUS_EFFECT_ACTIVE_QUIET_V1 (nog): the refusal's line at most once a minute a character (autohunt tried it every few seconds)
{
	static std::map<DWORD, DWORD> s_mapLastLine;
	DWORD& rdwLast = s_mapLastLine[GetPlayerID()];
	const DWORD dwNow = get_dword_time();
	if (!rdwLast || dwNow - rdwLast >= 60000)
	{
		rdwLast = dwNow;
		ChatPacket(CHAT_TYPE_INFO, LC_TEXT("This effect is already activated."));
	}
}

